"""Exact admission-correlated host callback successor; reject partial migrations."""

def rep(s, old, new):
    if s.count(old) != 1:
        raise SystemExit("refresh callback admission: source anchor changed")
    return s.replace(old, new, 1)

HOST_FRAGMENTS = ('    private var refreshRunID: String?\n    private var refreshAdmissionID: String?', '              V3ServiceBridge.strictBool(admission["admitted"]) == true,\n              let admissionID = admission["admissionID"] as? String,\n              UUID(uuidString: admissionID)?.uuidString == admissionID else {', '        refreshAdmissionID = admissionID\n        defer { if refreshAdmissionID == admissionID { refreshAdmissionID = nil } }\n        if let directClaimID {\n            sharedDefaults.set(["run_id": directClaimID,', 'client.refreshAllApps(withIdentifier: identifier, mangledTypeName: mangledName, refreshRunID: run, admissionID: admissionID)', 'private func releaseRefreshAdmission(_ runID: String, admissionID: String, terminalState: String)', 'payload: ["state": terminalState, "admissionID": admissionID])', 'guard reply["runID"] as? String == runID,\n                      reply["admissionID"] as? String == admissionID,\n                      V3ServiceBridge.strictBool(reply["released"]) == true else {', '    fileprivate func updateProgress(_ value: Double, id: UUID) {\n        guard refreshAdmissionID == nil else { return }\n        applyRefreshProgress(value, id: id)\n    }\n    fileprivate func updateHostProgress(_ value: Double, runID: String, admissionID: String, id: UUID) {\n        guard refreshRunID == runID, refreshAdmissionID == admissionID else { return }\n        applyRefreshProgress(value, id: id)\n    }\n    private func applyRefreshProgress(_ value: Double, id: UUID) {\n        guard launchID == id, refreshContinuation != nil, value.isFinite else { return }', '    fileprivate func completedRefresh(_ error: String?, runID: String, verification: Data?, id: UUID) {\n        // A legacy callback cannot settle a host-owned admission.\n        guard refreshAdmissionID == nil else { return }\n        acceptRefreshCompletion(error, runID: runID, verification: verification, id: id)\n    }\n    fileprivate func completedHostRefresh(_ error: String?, runID: String, admissionID: String, verification: Data?, id: UUID) {\n        guard V3RefreshCallbackIdentityPolicy.matches(\n            callbackRunID: runID, callbackAdmissionID: admissionID,\n            activeRunID: refreshRunID, activeAdmissionID: refreshAdmissionID) else { return }\n        acceptRefreshCompletion(error, runID: runID, verification: verification, id: id)\n    }\n    private func acceptRefreshCompletion(_ error: String?, runID: String, verification: Data?, id: UUID) {\n        guard launchID == id, refreshContinuation != nil, refreshRunID == runID else { return }', '    fileprivate func legacyCompletion(_ error: String?, id: UUID) {\n        guard refreshAdmissionID == nil else { return }\n        guard launchID == id,', '    func finishRefresh(_ error: String?, runID: String, verification: Data?) {\n        Task { @MainActor in self.owner?.completedRefresh(error, runID: runID, verification: verification, id: self.identity) }\n    }\n    func finishHostRefresh(_ error: String?, runID: String, admissionID: String, verification: Data?) {\n        Task { @MainActor in self.owner?.completedHostRefresh(error, runID: runID, admissionID: admissionID, verification: verification, id: self.identity) }\n    }\n    func updateHostProgress(_ value: Double, runID: String, admissionID: String) {\n        Task { @MainActor in self.owner?.updateHostProgress(value, runID: runID, admissionID: admissionID, id: self.identity) }\n    }', 'case "refreshAdmissionEnd":\n            return Set(payload.keys) == Set(["state", "admissionID"]) &&\n                canonicalSecretToken(payload["admissionID"]) &&', '// V3_REFRESH_CALLBACK_ADMISSION_V1: a run may contain multiple safe attempts.\nenum V3RefreshCallbackIdentityPolicy {\n    static func matches(callbackRunID: String, callbackAdmissionID: String,\n                        activeRunID: String?, activeAdmissionID: String?) -> Bool {\n        guard UUID(uuidString: callbackRunID)?.uuidString == callbackRunID,\n              UUID(uuidString: callbackAdmissionID)?.uuidString == callbackAdmissionID else { return false }\n        return callbackRunID == activeRunID && callbackAdmissionID == activeAdmissionID\n    }\n}')

def validate_host(s):
    for fragment in HOST_FRAGMENTS:
        if fragment.startswith('case "refreshAdmissionEnd":') and 'case "refreshAdmissionEnd":' not in s:
            continue
        if fragment not in s:
            raise SystemExit("refresh callback admission: host successor changed")

def install_host(s):
    if 'enum V3RefreshCallbackIdentityPolicy' in s:
        validate_host(s)
        return s
    s = rep(s, '    private var refreshRunID: String?', '    private var refreshRunID: String?\n    private var refreshAdmissionID: String?')
    s = rep(s, '              V3ServiceBridge.strictBool(admission["admitted"]) == true else {', '              V3ServiceBridge.strictBool(admission["admitted"]) == true,\n              let admissionID = admission["admissionID"] as? String,\n              UUID(uuidString: admissionID)?.uuidString == admissionID else {')
    s = rep(s, '        if let directClaimID {\n            sharedDefaults.set(["run_id": directClaimID,', '        refreshAdmissionID = admissionID\n        defer { if refreshAdmissionID == admissionID { refreshAdmissionID = nil } }\n        if let directClaimID {\n            sharedDefaults.set(["run_id": directClaimID,')
    s = rep(s, 'client.refreshAllApps(withIdentifier: identifier, mangledTypeName: mangledName, refreshRunID: run)', 'client.refreshAllApps(withIdentifier: identifier, mangledTypeName: mangledName, refreshRunID: run, admissionID: admissionID)')
    s = s.replace('releaseRefreshAdmission(run,', 'releaseRefreshAdmission(run, admissionID: admissionID,')
    s = rep(s, 'private func releaseRefreshAdmission(_ runID: String, terminalState: String)', 'private func releaseRefreshAdmission(_ runID: String, admissionID: String, terminalState: String)')
    s = rep(s, 'payload: ["state": terminalState])', 'payload: ["state": terminalState, "admissionID": admissionID])')
    s = rep(s, 'guard reply["runID"] as? String == runID,\n                      V3ServiceBridge.strictBool(reply["released"]) == true else {', 'guard reply["runID"] as? String == runID,\n                      reply["admissionID"] as? String == admissionID,\n                      V3ServiceBridge.strictBool(reply["released"]) == true else {')
    s = rep(s, '    fileprivate func updateProgress(_ value: Double, id: UUID) {\n        guard launchID == id, refreshContinuation != nil, value.isFinite else { return }', '    fileprivate func updateProgress(_ value: Double, id: UUID) {\n        guard refreshAdmissionID == nil else { return }\n        applyRefreshProgress(value, id: id)\n    }\n    fileprivate func updateHostProgress(_ value: Double, runID: String, admissionID: String, id: UUID) {\n        guard refreshRunID == runID, refreshAdmissionID == admissionID else { return }\n        applyRefreshProgress(value, id: id)\n    }\n    private func applyRefreshProgress(_ value: Double, id: UUID) {\n        guard launchID == id, refreshContinuation != nil, value.isFinite else { return }')
    s = rep(s, '    fileprivate func completedRefresh(_ error: String?, runID: String, verification: Data?, id: UUID) {\n        guard launchID == id, refreshContinuation != nil, refreshRunID == runID else { return }', '    fileprivate func completedRefresh(_ error: String?, runID: String, verification: Data?, id: UUID) {\n        // A legacy callback cannot settle a host-owned admission.\n        guard refreshAdmissionID == nil else { return }\n        acceptRefreshCompletion(error, runID: runID, verification: verification, id: id)\n    }\n    fileprivate func completedHostRefresh(_ error: String?, runID: String, admissionID: String, verification: Data?, id: UUID) {\n        guard V3RefreshCallbackIdentityPolicy.matches(\n            callbackRunID: runID, callbackAdmissionID: admissionID,\n            activeRunID: refreshRunID, activeAdmissionID: refreshAdmissionID) else { return }\n        acceptRefreshCompletion(error, runID: runID, verification: verification, id: id)\n    }\n    private func acceptRefreshCompletion(_ error: String?, runID: String, verification: Data?, id: UUID) {\n        guard launchID == id, refreshContinuation != nil, refreshRunID == runID else { return }')
    s = rep(s, '    fileprivate func legacyCompletion(_ error: String?, id: UUID) {\n        guard launchID == id,', '    fileprivate func legacyCompletion(_ error: String?, id: UUID) {\n        guard refreshAdmissionID == nil else { return }\n        guard launchID == id,')
    s = rep(s, '    func finishRefresh(_ error: String?, runID: String, verification: Data?) {\n        Task { @MainActor in self.owner?.completedRefresh(error, runID: runID, verification: verification, id: self.identity) }\n    }', '    func finishRefresh(_ error: String?, runID: String, verification: Data?) {\n        Task { @MainActor in self.owner?.completedRefresh(error, runID: runID, verification: verification, id: self.identity) }\n    }\n    func finishHostRefresh(_ error: String?, runID: String, admissionID: String, verification: Data?) {\n        Task { @MainActor in self.owner?.completedHostRefresh(error, runID: runID, admissionID: admissionID, verification: verification, id: self.identity) }\n    }\n    func updateHostProgress(_ value: Double, runID: String, admissionID: String) {\n        Task { @MainActor in self.owner?.updateHostProgress(value, runID: runID, admissionID: admissionID, id: self.identity) }\n    }')
    policy = '// V3_REFRESH_CALLBACK_ADMISSION_V1: a run may contain multiple safe attempts.\nenum V3RefreshCallbackIdentityPolicy {\n    static func matches(callbackRunID: String, callbackAdmissionID: String,\n                        activeRunID: String?, activeAdmissionID: String?) -> Bool {\n        guard UUID(uuidString: callbackRunID)?.uuidString == callbackRunID,\n              UUID(uuidString: callbackAdmissionID)?.uuidString == callbackAdmissionID else { return false }\n        return callbackRunID == activeRunID && callbackAdmissionID == activeAdmissionID\n    }\n}\n\n'
    s = rep(s, '@MainActor\nclass RefreshHandler: NSObject {', policy + '@MainActor\nclass RefreshHandler: NSObject {')
    if 'case "refreshAdmissionEnd":' in s:
        s = rep(s, 'case "refreshAdmissionEnd":\n            return Set(payload.keys) == Set(["state"]) &&', 'case "refreshAdmissionEnd":\n            return Set(payload.keys) == Set(["state", "admissionID"]) &&\n                canonicalSecretToken(payload["admissionID"]) &&')
    validate_host(s)
    return s

HEADER_FRAGMENTS = ('// V3_REFRESH_CALLBACK_ADMISSION_V1\n- (void)finishHostRefresh:(NSString* _Nullable)error runID:(NSString* _Nonnull)runID admissionID:(NSString* _Nonnull)admissionID verification:(NSData* _Nullable)verification NS_SWIFT_NAME(finishHostRefresh(_:runID:admissionID:verification:));\n- (void)updateHostProgress:(double)value runID:(NSString* _Nonnull)runID admissionID:(NSString* _Nonnull)admissionID NS_SWIFT_NAME(updateHostProgress(_:runID:admissionID:));\n- (void)onConnection:(NSXPCConnection*)connection;', '- (void)refreshAllAppsWithIdentifier:(NSString*)identifier mangledTypeName:(NSString *)mangledTypeName refreshRunID:(NSString* _Nullable)refreshRunID;\n- (void)refreshAllAppsWithIdentifier:(NSString*)identifier mangledTypeName:(NSString *)mangledTypeName refreshRunID:(NSString* _Nonnull)refreshRunID admissionID:(NSString* _Nonnull)admissionID NS_SWIFT_NAME(refreshAllApps(withIdentifier:mangledTypeName:refreshRunID:admissionID:));')

def validate_header(s):
    for fragment in HEADER_FRAGMENTS:
        if fragment not in s:
            raise SystemExit("refresh callback admission: header successor changed")

def install_header(s):
    if 'V3_REFRESH_CALLBACK_ADMISSION_V1' in s:
        validate_header(s)
        return s
    s = rep(s, '- (void)onConnection:(NSXPCConnection*)connection;', '// V3_REFRESH_CALLBACK_ADMISSION_V1\n- (void)finishHostRefresh:(NSString* _Nullable)error runID:(NSString* _Nonnull)runID admissionID:(NSString* _Nonnull)admissionID verification:(NSData* _Nullable)verification NS_SWIFT_NAME(finishHostRefresh(_:runID:admissionID:verification:));\n- (void)updateHostProgress:(double)value runID:(NSString* _Nonnull)runID admissionID:(NSString* _Nonnull)admissionID NS_SWIFT_NAME(updateHostProgress(_:runID:admissionID:));\n- (void)onConnection:(NSXPCConnection*)connection;')
    s = rep(s, '- (void)refreshAllAppsWithIdentifier:(NSString*)identifier mangledTypeName:(NSString *)mangledTypeName refreshRunID:(NSString* _Nullable)refreshRunID;', '- (void)refreshAllAppsWithIdentifier:(NSString*)identifier mangledTypeName:(NSString *)mangledTypeName refreshRunID:(NSString* _Nullable)refreshRunID;\n- (void)refreshAllAppsWithIdentifier:(NSString*)identifier mangledTypeName:(NSString *)mangledTypeName refreshRunID:(NSString* _Nonnull)refreshRunID admissionID:(NSString* _Nonnull)admissionID NS_SWIFT_NAME(refreshAllApps(withIdentifier:mangledTypeName:refreshRunID:admissionID:));')
    validate_header(s)
    return s

